//
// ============================================================================
//  📘 دليل التعديل السريع — اقرأ هذا قبل ما تضيف أي حاجة
// ============================================================================
//
//  1) لإضافة "شرح/معلومة" جديدة في أي درس:
//     روح لمصفوفة points:[ ...] بتاعة الدرس، هتلاقي سطر تعليق أخضر مكتوب فيه
//     "👉 [أضف هنا]" — ده بالظبط المكان اللي تحط فيه سطر جديد بنفس الصيغة:
//         "<b>مصطلح مهم:</b> شرح مختصر وواضح للنقطة."
//     ملحوظة: أي سطر يبدأ بـ // هو تعليق للمبرمج فقط ولن يظهر في التطبيق أبدًا.
//
//  2) لإضافة "مصطلح فليب-كارد" جديد (البطاقة اللي بتتقلب):
//     روح لمصفوفة terms:[ ...] بتاعة الدرس وزوّد عنصر جديد بنفس الصيغة:
//         {t:"اسم المصطلح", d:"تعريفه المختصر."}
//
//  3) لإضافة "سؤال" جديد في أي درس:
//     روح لمصفوفة quiz:[ ...] بتاعة الدرس، هتلاقي تعليق موضح فيه 3 أنواع أسئلة مدعومة:
//
//     🔘 اختيار من متعدد (mcq):
//        {type:"mcq", q:"نص السؤال؟", opts:["اختيار1","اختيار2","اختيار3"], a:0, ex:"شرح الإجابة الصحيحة."}
//        → a هو رقم الاختيار الصحيح بدءًا من صفر (0 = أول اختيار، 1 = ثاني اختيار...)
//
//     ✅ صح أو خطأ (tf):
//        {type:"tf", q:"عبارة تحتاج تقييم صح أو خطأ.", a:true, ex:"شرح الإجابة."}
//        → a يكون true (صح) أو false (خطأ)
//
//     ✍️ إكمال الفراغ (fill):
//        {type:"fill", q:"أكمل الفراغ: عاصمة مصر هي ____", answer:"القاهرة", ex:"شرح إضافي اختياري."}
//        → answer هو النص المتوقع (المقارنة لا تفرّق بين كبيرة وصغيرة الحروف ولا تحتاج تطابق حرفي كامل)
//
//  4) لإضافة "درس" جديد كامل داخل وحدة موجودة، أو "وحدة" جديدة بالكامل:
//     انزل لآخر هذا الملف، هتلاقي "قالب جاهز للنسخ" (Template) داخل تعليق طويل —
//     انسخه، الصقه في المكان المناسب، وعدّل القيم بين علامات الاقتباس.
//
//  📹 لإضافة روابط شرح فيديو/بث مباشر لأي درس:
//     كل درس فيه حقل links:{tiktok:"", youtube:"", facebook:"", zoom:"", googleMeet:""}
//     موجود مباشرة قبل مصفوفة quiz:[ الخاصة به. الصق رابط الفيديو/المحاضرة بين علامتي
//     الاقتباس للمنصة المناسبة، واترك البقية فارغة "" لو مفيش رابط لها. مثال:
//     links:{tiktok:"https://www.tiktok.com/@user/video/123", youtube:"https://youtu.be/xxxx",
//            facebook:"", zoom:"https://zoom.us/j/xxxxxxx", googleMeet:""}
//     أي رابط تسيبه فاضي "" مش هيظهر زراره للطالب تلقائيًا — بس اللي تحطه هو اللي هيظهر.
//
//  5) لإضافة "تدريب" إضافي (منفصل عن اختبر نفسك) في أي درس:
//     كل درس فيه مصفوفة practice:[ ...] بنفس صيغة أسئلة quiz بالضبط (mcq / tf / fill).
//     هذه الأسئلة تظهر في بطاقة "🧩 تدريبات إضافية" أسفل بطاقة "اختبر نفسك" في شاشة الدرس،
//     ولازم الطالب يجاوب عليها كلها (مع باقي شروط الوحدة) قبل ما يقدر يفتح الاختبار الشامل ويفتح الوحدة التالية.
//
//  6) لإضافة سؤال في "الاختبار الشامل" لوحدة معينة:
//     كل وحدة فيها مصفوفة finalTest:[ ...] بنفس صيغة أسئلة quiz بالضبط (مسموح أكثر من 8 أسئلة —
//     التطبيق يختار 8 عشوائيًا من المصفوفة، ويخلط ترتيب اختيارات كل سؤال mcq، في كل محاولة اختبار).
//     زوّد أسئلة أكتر هنا كل ما احتجت تنويع أكبر للاختبار.
//
//  7) بعد أي تعديل: احفظ الملف فقط، مفيش حاجة تانية تعملها — التطبيق هيقرأ التغييرات تلقائيًا
//     أول ما تفتح ملف index.html في المتصفح (أو تعمل تحديث/Refresh للصفحة لو كانت مفتوحة).
// ============================================================================

// ---------- مولّد بلوكات الكود بشكل VS Code / تيرمينال ----------
// الاستخدام داخل أي حقل example هنا تحت:
//   codeBlock('print("hello")', 'main.py')          -> شكل محرر VS Code بعنوان الملف
//   codeBlock('pip install requests', null, true)   -> شكل تيرمينال (سطر أوامر)
function codeBlock(code, filename, isTerminal){
  const escaped = String(code)
    .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  const label = isTerminal ? 'Terminal' : (filename || 'code');
  return `<div class="code-block${isTerminal ? ' terminal' : ''}">`
    + `<div class="code-titlebar"><span class="code-dots"><span></span><span></span><span></span></span>`
    + `<span class="code-filename">${label}</span></div>`
    + `<pre><code>${escaped}</code></pre></div>`;
}

