//  🎓 نطاق الجوائز والشهادات — يختلف تلقائيًا حسب الصف اللي اختاره الطالب في مودال البداية
//  '1sec' (الصف الأول الثانوي): يُحسب من UNITS (13 وحدة) + FINAL_EXAMS (5 امتحانات) = 18 تقييمًا.
//  '2bac'  (الصف الثاني بكالوريا): يُحسب من BAC2_UNITS + BAC2_EXAMS تلقائيًا فور إضافتهم لاحقًا —
//  لحد ما يتضاف محتوى فعلي، المصفوفتان فاضيتان فيبقى لسه مفيش شهادة تظهر لطالب هذا الصف (سلوك آمن).
// ============================================================================
// 🔒 امتحانات الصف الثاني بكالوريا مقفولة لحد ما المنهج ينزل كامل. لما تخلّص كل الأجزاء وتضيف
// BAC2_EXAMS: غيّر القيمة دي لـ true عشان تتفتح الامتحانات للصف ده.
const BAC2_CURRICULUM_COMPLETE = false;
const BAC2_EXAMS = [
  // نفس شكل FINAL_EXAMS بالظبط: { id:1, title:"...", questions:[...] } — يُضاف لاحقًا مع محتوى الصف.
];
function certScope(){
  if(typeof STATE !== 'undefined' && STATE.currentGrade === '2bac'){
    return { units: BAC2_UNITS, exams: BAC2_EXAMS, gradeLabel: (typeof GRADE_NAMES!=='undefined' && GRADE_NAMES['2bac']) || 'الصف الثاني بكالوريا' };
  }
  return { units: UNITS, exams: FINAL_EXAMS, gradeLabel: (typeof GRADE_NAMES!=='undefined' && GRADE_NAMES['1sec']) || 'الصف الأول الثانوي' };
}

